local function PlayerPosition()
    if APR.GetNavigationPlayerPosition then return APR:GetNavigationPlayerPosition() end
    local x, y, z, instanceID = Call(UnitPosition, "player")
    if not Number(x) or not Number(y) or not Number(instanceID) then return nil end
    local mapID = C_Map and Call(C_Map.GetBestMapForUnit, "player")
    if not Number(mapID) then return nil end
    local data = APR.NavigationData
    if data and data.GetWorldInstanceID then instanceID = data:GetWorldInstanceID(instanceID) end
    return { x = x, y = y, z = Number(z) and z or nil, instanceID = instanceID, uiMapID = mapID }
end--[[APR_DIAG]]; PlayerPosition = APRTrace("APR-Core/features/navigation/NavigationAdapter.lua:48:PlayerPosition#8", PlayerPosition)--[[/APR_DIAG]]

